#!/usr/bin/env bash
set -Eeuo pipefail
rsync_owned() { local src=$1 dest=$2; shift 2; local args=(-az --delete --exclude node_modules --exclude tests --exclude runtime --exclude .DS_Store --exclude '.env*' --exclude '*~'); [ "$DRY_RUN" -eq 1 ] && args+=(--dry-run); args+=("$@"); args+=(-e "$(rsync_ssh_command)"); rsync "${args[@]}" "$src/" "$PRODUCTION_SSH_USER@$PRODUCTION_SSH_HOST:$dest/"; }
sync_theme_dist() { local theme_src=$1 theme_dest=$2 dist_src="$1/assets/dist" dist_dest="$2/assets/dist"; [ "$DRY_RUN" -eq 1 ] || remote_exec "mkdir -p $(shell_quote "$dist_dest")" || return 1; local copy_args=(-az --exclude manifest.json); [ "$DRY_RUN" -eq 1 ] && copy_args+=(--dry-run); copy_args+=(-e "$(rsync_ssh_command)"); rsync "${copy_args[@]}" "$dist_src/" "$PRODUCTION_SSH_USER@$PRODUCTION_SSH_HOST:$dist_dest/" || return 1; local manifest_args=(-az); [ "$DRY_RUN" -eq 1 ] && manifest_args+=(--dry-run); manifest_args+=(-e "$(rsync_ssh_command)"); rsync "${manifest_args[@]}" "$dist_src/manifest.json" "$PRODUCTION_SSH_USER@$PRODUCTION_SSH_HOST:$dist_dest/manifest.json" || return 1; rsync_owned "$dist_src" "$dist_dest" --exclude manifest.json || return 1; }
verify_remote_theme_assets() { local theme_dest=$1; remote_exec "php -r '\$dist = realpath(\$argv[1] . \"/assets/dist\"); \$manifest_path = \$dist . \"/manifest.json\"; if (!\$dist || !is_readable(\$manifest_path)) exit(1); \$manifest = json_decode(file_get_contents(\$manifest_path), true); if (!is_array(\$manifest)) exit(1); \$prefix = rtrim(\$dist, DIRECTORY_SEPARATOR) . DIRECTORY_SEPARATOR; \$valid = function (\$file) use (\$dist, \$prefix) { if (!is_string(\$file) || \$file === \"\") return false; \$target = realpath(\$dist . \"/\" . \$file); return \$target && strpos(\$target, \$prefix) === 0 && is_file(\$target); }; \$main = false; foreach (\$manifest as \$entry) { if (!is_array(\$entry) || !isset(\$entry[\"file\"]) || !\$valid(\$entry[\"file\"])) exit(1); foreach (array(\"css\", \"assets\") as \$field) { if (isset(\$entry[\$field]) && !is_array(\$entry[\$field])) exit(1); foreach (\$entry[\$field] ?? array() as \$file) if (!\$valid(\$file)) exit(1); } foreach (array(\"imports\", \"dynamicImports\") as \$field) { if (isset(\$entry[\$field]) && !is_array(\$entry[\$field])) exit(1); foreach (\$entry[\$field] ?? array() as \$reference) if (!is_string(\$reference) || !array_key_exists(\$reference, \$manifest)) exit(1); } if (isset(\$entry[\"name\"]) && \$entry[\"name\"] === \"main\") { if (pathinfo(\$entry[\"file\"], PATHINFO_EXTENSION) !== \"js\") exit(1); \$main = true; } } exit(\$main ? 0 : 1);' $(shell_quote "$theme_dest")" || die 6 'deployed theme asset manifest is invalid'; }
deploy_owned_code() { PHASE=code; local theme_src="$PROJECT_ROOT/theme/rentacar-venezia-v2" theme_dest="$PRODUCTION_ROOT/wp-content/themes/rentacar-venezia-v2"; dry "would rsync owned theme and plugin only; --delete is scoped to those directories"; info 'deploying owned theme files before its asset manifest'; rsync_owned "$theme_src" "$theme_dest" --exclude '/assets/dist/***' || die 6 'theme rsync failed'; info 'deploying complete theme asset build before its manifest'; sync_theme_dist "$theme_src" "$theme_dest" || die 6 'theme asset rsync failed'; info 'deploying rentacar-core with rsync'; rsync_owned "$PROJECT_ROOT/plugin/rentacar-core" "$PRODUCTION_ROOT/wp-content/plugins/rentacar-core" || die 6 'rentacar-core rsync failed'; [ "$DRY_RUN" -eq 1 ] && return; verify_remote_theme_assets "$theme_dest"; info 'validating deployed PHP files'; remote_exec "test -f $(shell_quote "$theme_dest/style.css") && test -f $(shell_quote "$PRODUCTION_ROOT/wp-content/plugins/rentacar-core/rentacar-core.php") && find $(shell_quote "$theme_dest") $(shell_quote "$PRODUCTION_ROOT/wp-content/plugins/rentacar-core") -name '*.php' -type f -exec php -l {} \\;" || die 6 'remote code validation failed'; }
code_failure_rollback() { [ "$AUTO_ROLLBACK_CODE_FAILURE" -eq 1 ] && [ "$NO_AUTO_ROLLBACK" -ne 1 ] || die 7 'code verification failed'; warn 'verification failed; restoring owned code backup'; local d; d=$(remote_backup_dir); remote_exec "cd $(shell_quote "$PRODUCTION_ROOT") && rm -rf wp-content/themes/rentacar-venezia-v2 wp-content/plugins/rentacar-core && tar -xzf $(shell_quote "$d/rentacar-venezia-v2-before.tar.gz") && tar -xzf $(shell_quote "$d/rentacar-core-before.tar.gz")" || die 8 'automatic code rollback failed'; flush_caches; die 7 'code verification failed; owned code was restored'; }
